style.css:
@-moz-document domain("youtube.com"), domain("youtube-nocookie.com") {
/* Player arredondado e sombra suave */
  .html5-video-player {
    border-radius: 16px !important;
    overflow: hidden !important;
    box-shadow: 0 0 20px rgba(0,255,170,0.3), 0 0 40px rgba(0,229,255,0.2) !important;
  }

  /* Barra inferior (glass) */
  .ytp-chrome-bottom {
    background: rgba(25,25,25,0.2) !important;
    backdrop-filter: blur(14px) saturate(150%) !important;
    border-radius: 0 0 14px 14px !important;
    padding: 6px 12px !important;
    display: flex !important;
    align-items: center;
  }

  /* Todos os botões do player em glass */
  .ytp-button,
  .ytp-prev-button,
  .ytp-next-button,
  .ytp-fullscreen-button,
  .ytp-miniplayer-button,
  .ytp-subtitles-button,
  .ytp-settings-button {
    background: rgba(255,255,255,0.08) !important;
    backdrop-filter: blur(12px) saturate(150%) !important;
    border-radius: 12px !important;
    padding: 6px !important;
    margin: 0 2px !important;
    box-shadow: 0 0 8px rgba(0,255,170,0.4), 0 0 14px rgba(0,229,255,0.25) !important;
    transition: transform .15s ease, background .15s ease !important;
  }
  .ytp-button:hover {
    transform: scale(1.1);
    background: rgba(255,255,255,0.12) !important;
  }

  /* Botão play circular */
  .ytp-play-button {
    border-radius: 50% !important;
    width: 48px !important;
    height: 48px !important;
    display: flex !important;
    align-items: center;
    justify-content: center;
  }

  /* Horas do vídeo */
  .ytp-time-display {
    background: rgba(255,255,255,0.07) !important;
    backdrop-filter: blur(10px) saturate(150%) !important;
    border-radius: 8px !important;
    padding: 2px 6px !important;
    font-size: 12px !important;
    color: #00ffaa !important;
    text-shadow: 0 0 3px rgba(0,255,170,0.4);
  }

  /* Barra de progresso */
  .ytp-progress-bar-container {
    height: 6px !important;
    border-radius: 8px !important;
    background: rgba(255,255,255,0.05) !important;
    backdrop-filter: blur(10px) saturate(150%) !important;
  }
  .ytp-play-progress {
    border-radius: 8px !important;
    background: linear-gradient(90deg, #00ffaa, #00e5ff, #ff00ff) !important;
    box-shadow: 0 0 10px rgba(0,255,170,0.5), 0 0 14px rgba(0,229,255,0.3) !important;
  }
  .ytp-load-progress {
    background: rgba(255,255,255,0.12) !important;
  }
  .ytp-hover-progress {
    background: rgba(0,229,255,0.2) !important;
  }

  /* Volume slider */
  .ytp-volume-slider-handle {
    background: #00e5ff !important;
    border-radius: 50% !important;
    width: 12px !important;
    height: 12px !important;
  }
  .ytp-volume-slider-track {
    background: rgba(255,255,255,0.2) !important;
    border-radius: 10px !important;
  }
  .ytp-volume-slider-active {
    background: linear-gradient(90deg,#00ffaa,#00e5ff) !important;
  }

  /* Tooltip do tempo */
  .ytp-tooltip {
    background: rgba(20,20,20,0.9) !important;
    border: 1px solid rgba(0,255,170,0.5) !important;
    border-radius: 8px !important;
    font-size: 12px !important;
    padding: 3px 6px !important;
    color: #00ffaa !important;
    text-shadow: 0 0 4px rgba(0,255,170,0.4);
  }
}
